    NativeBandAcousticPredictor,
    _check_state,
    _configuration,
)
from marine_echo.training import native_band_replication_ssl as core
from marine_echo.training import native_band_ssl as original_core

ARCHITECTURE = core.ARCHITECTURE

IMPLEMENTER_SESSION_ID = "01a0ef20-7397-7ba1-a98c-f59bc38ddcc1"
MODES = ("frozen_readout", "full_finetune", "direct_end_to_end")
METHODS = core.METHODS
sha256 = core.sha256


@dataclass(frozen=True)
class DownstreamConfig:
    architecture: str = ARCHITECTURE
    mode: str = "frozen_readout"
    method: str = "shared_ssl"
    seed: int = 7
    history: int = 96
    updates: int | None = None
    cadence: int | None = None
    patience: int = 4
    min_daily_anchors: int = 18
    batch_size: int = 64
    lr: float = 0.0003
    weight_decay: float = 0.0001
    gradient_clip: float = 1.0
    selection_policy: str = "scheduled_native_daily_pinball_earliest_strict_improvement_v1"

    def __post_init__(self):
        if self.updates is None:
            object.__setattr__(self, "updates", 2000 if self.mode == "frozen_readout" else 3000)
        if self.cadence is None:
            object.__setattr__(self, "cadence", 500 if self.mode == "frozen_readout" else 750)

    def to_dict(self):
        return asdict(self)

    def validate(self, *, correctness_smoke=False):
        if (self.lr, self.weight_decay, self.gradient_clip) != (0.0003, 0.0001, 1.0):
            raise ValueError("Band downstream optimizer/clipping are frozen.")
        if any(
            type(getattr(self, name)) is not int
            for name in (
                "seed",
                "history",
                "updates",
                "cadence",
                "patience",
                "min_daily_anchors",
                "batch_size",
            )
        ):
            raise ValueError("Downstream dimensions/budgets must be exact integers.")
        if any(
            not isinstance(getattr(self, name), (int, float))
            or isinstance(getattr(self, name), bool)
            or not np.isfinite(getattr(self, name))
            for name in ("lr", "weight_decay", "gradient_clip")
        ):
            raise ValueError("Downstream numeric configuration must be finite.")
        if self.architecture != ARCHITECTURE:
            raise ValueError("Exact band downstream architecture required.")
        if self.mode not in MODES or self.method not in METHODS:
            raise ValueError("Unsupported downstream mode/method.")
        if self.mode == "direct_end_to_end" and self.method != "direct":
            raise ValueError("direct_end_to_end requires the direct method and no ancestor.")
        if self.seed not in (7, 13, 23) or self.history != 96:
            raise ValueError("Band downstream requires admitted seed7/13/23 and H96.")
        if not isinstance(self.updates, int) or not 1 <= self.updates <= 5000:
            raise ValueError("Hard supervised trajectory limit is5000 updates.")
        if not isinstance(self.cadence, int) or not 1 <= self.cadence <= self.updates:
            raise ValueError("Invalid checkpoint cadence.")
        if self.batch_size < 1 or self.lr <= 0 or self.weight_decay < 0:
            raise ValueError("Invalid optimizer configuration.")
        if self.patience != 4 or self.min_daily_anchors != 18 or self.gradient_clip != 1:
            raise ValueError("Patience4, daily floor18, and gradient clipping1 are fixed.")
        if (
            self.selection_policy
            != DownstreamConfig.__dataclass_fields__["selection_policy"].default
        ):
            raise ValueError("Unsupported checkpoint selection policy.")
        if not correctness_smoke:
            budget = (2000, 500) if self.mode == "frozen_readout" else (3000, 750)
            if (self.updates, self.cadence) != budget or (
                self.batch_size,
                self.lr,
                self.weight_decay,
            ) != (64, 0.0003, 0.0001):
                raise ValueError(
                    "Real downstream runs require the frozen endpoint budget/optimizer."
                )


@dataclass(frozen=True)
class RunInputs:
    train: Path
    dev: Path
    train_cohort: Path
    dev_cohort: Path
    split: Path
    adr0016: Path
    protocol: Path
    config: Path
    review: Path
    encoder: Path | None = None
    ancestor_review: Path | None = None
    ancestor_config: Path | None = None


def _json(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _write_json(path, value):
    Path(path).write_text(
        json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8"
    )


def _ancestor_paths(inputs):
    if inputs.encoder is None:
        return []
    parent = Path(inputs.encoder).parent
    if inputs.ancestor_review is None:
        raise ValueError("Pretrained transfer requires the original independent ancestor review.")
    return [
        Path(inputs.encoder),
        parent / "run.json",
        parent / "inference.pt",
        parent / "membership.json",
        inputs.ancestor_config or parent / "config.json",
        Path(inputs.ancestor_review),
    ]


def required_paths(inputs, core_config):
    """All project helper/source files and lineage artifacts required in review."""
    paths = [
        Path(__file__),
        inputs.train,
        inputs.dev,
        inputs.train_cohort,
        inputs.dev_cohort,
        inputs.split,
        inputs.adr0016,
        inputs.protocol,
        inputs.config,
        *core.required_sources(core_config),
        *_ancestor_paths(inputs),
    ]
    source = core.HELPER_ROOT
    paths += [
        source / "__init__.py",
        source / "training/__init__.py",
        source / "models/__init__.py",
        source / "data/native_ssl_corpus.py",
        source / "training/aeon_corpus.py",
    ]
    if inputs.review.exists():
        budget = _json(inputs.review).get("budget_resolution_path")
        if budget:
            paths.append(Path(budget))
    return list(dict.fromkeys(Path(p).resolve() for p in paths))


def _distinct_review(review, *, status, implementer):
    if review.get("status") != status:
        raise ValueError(f"Independent {status} review required before fitting.")
    reviewer = review.get("reviewer_session_id")
    author = review.get("implementer_session_id")
    excluded = (author, implementer, review.get("root_coordinator_session_id"))
    if (
        not author
        or not isinstance(reviewer, str)
        or not reviewer
        or reviewer != reviewer.strip()
        or reviewer.casefold() in {str(v).casefold() for v in excluded}
    ):
        raise ValueError("Reviewer must be a distinct session from the implementer.")


def _bindings(record, paths):
    bindings = record.get("bindings")
    if not isinstance(bindings, dict) or not bindings:
        raise ValueError("Required bindings are missing.")
    for path in paths:
        if bindings.get(str(Path(path).resolve())) != sha256(Path(path)):
            raise ValueError(f"Missing or stale binding: {path}")


def _cohort(inputs, role):
    path, payload = (
        (inputs.train_cohort, inputs.train) if role == "train" else (inputs.dev_cohort, inputs.dev)
    )
    record = _json(path)
    if record.get("role") != role:
        raise ValueError("Only train/development cohort roles are admitted; test remains closed.")
    if record.get("npz_sha256") != sha256(payload) or record.get("split_sha256") != sha256(
        inputs.split
    ):
        raise ValueError("Cohort data/split ancestry mismatch.")
    return record


def _split_roles(inputs):
    sources = _json(inputs.split).get("sources", [])
    if not isinstance(sources, list) or any(
        s.get("role") not in ("train", "development", "final_test")
        or not s.get("deployment")
        or not s.get("archive_sha256")
        for s in sources
    ):
        raise ValueError("Invalid declared split source roles.")
    if len({s["deployment"] for s in sources}) != len(sources):
        raise ValueError("Split repeats a source/deployment identity.")
    by_role = {
        r: {s["deployment"]: s["archive_sha256"] for s in sources if s["role"] == r}
        for r in ("train", "development", "final_test")
    }
    if not by_role["train"] or not by_role["development"]:
        raise ValueError("TRAIN/development split membership is required.")
    for a, b in (("train", "development"), ("train", "final_test"), ("development", "final_test")):
        if set(by_role[a]) & set(by_role[b]) or set(by_role[a].values()) & set(by_role[b].values()):
            raise ValueError("Split source/deployment roles overlap.")
    return by_role


def check_prefit(inputs, config, core_config, *, correctness_smoke=False):
    """No NumPy payload or torch checkpoint loading occurs until this succeeds."""
    review = _json(inputs.review)
    expected_kind = (
        "SYNTHETIC_CORRECTNESS_ONLY" if correctness_smoke else "REAL_TRAIN_DEVELOPMENT_FIT"
    )
    if (
        review.get("architecture") != ARCHITECTURE
        or review.get("evidence_kind") != expected_kind
        or set(review.get("allowed_roles", [])) != {"train", "development"}
    ):
        raise ValueError(
            "Downstream review must explicitly admit band architecture/evidence/roles."
        )
    if not correctness_smoke:
        budget_path = review.get("budget_resolution_path")
        if review.get("band_budget_status") != "ROOT_RESOLVED" or not budget_path:
            raise ValueError("Root must resolve the screen/endpoint budget before new prefit.")
        _bindings(review, [Path(budget_path)])
        core._check_budget(review)
    _distinct_review(
        review, status="APPROVED_DOWNSTREAM_PREFIT", implementer=IMPLEMENTER_SESSION_ID
    )
    if review.get("implementer_session_id") != IMPLEMENTER_SESSION_ID:
        raise ValueError("Downstream review does not identify this implementation session.")
    if config.seed not in review.get("allowed_seeds", []):
        raise ValueError("Seed is outside the exact independent replication review.")
    if config.mode not in review.get("allowed_modes", []) or config.method not in review.get(
        "allowed_methods", []
    ):
        raise ValueError("Mode/method is not approved for downstream fitting.")
    _bindings(review, required_paths(inputs, core_config))
    for key, path in (
        ("train_npz_sha256", inputs.train),
        ("dev_npz_sha256", inputs.dev),
        ("split_sha256", inputs.split),
    ):
        if review.get(key) != sha256(path):
            raise ValueError(f"Review identity mismatch: {key}")
    if _json(inputs.config) != config.to_dict():
        raise ValueError("Runtime downstream config differs from reviewed config.")
    if correctness_smoke and review.get("correctness_core_config") != core_config.to_dict():
        raise ValueError("CPU correctness architecture is not explicitly bound in review.")
    _split_roles(inputs)
    _cohort(inputs, "train")
    _cohort(inputs, "development")
    if inputs.encoder is not None:
        paths = _ancestor_paths(inputs)
        parent = _json(paths[1])
        if _parent_core(inputs) is original_core and core_config.seed != 7:
            raise ValueError(
                "Original version1 parent cannot supply seed13/23 replication features."
            )
        parent_review = _json(paths[5])
        _distinct_review(
            parent_review, status="APPROVED_PREFIT", implementer=core.IMPLEMENTER_SESSION_ID
        )
        if config.method not in parent_review.get("allowed_methods", []):
            raise ValueError("Ancestor method was not independently approved.")
        required = [
            inputs.train,
            inputs.dev,
            inputs.split,
            inputs.adr0016,
            paths[4],
            *_parent_core(inputs).required_sources(core_config),
        ]
        for path in required:
            path = Path(path).resolve()
            expected = sha256(path)
            historical = parent.get("bindings", {}).get(str(path))
            if (
                historical != expected
                or parent_review.get("bindings", {}).get(str(path)) != expected
            ):
                raise ValueError(f"Ancestor original source/data binding differs: {path}")
        if (
            parent.get("config") != core_config.to_dict()
            or _json(paths[4]) != core_config.to_dict()
        ):
            raise ValueError("Ancestor config identity mismatch.")
        # Reviews also bind cohort reports, tests and operational evidence; the
        # fit's minimal ancestry map must be contained in that complete review.
        if any(
            parent_review.get("bindings", {}).get(path) != expected
            for path, expected in parent.get("bindings", {}).items()
        ):
            raise ValueError("Ancestor review/run source bindings differ.")
        for key, path in (
            ("train_npz_sha256", inputs.train),
            ("dev_npz_sha256", inputs.dev),
            ("split_sha256", inputs.split),
            ("protocol_sha256", inputs.adr0016),
        ):
            if parent_review.get(key) != sha256(path):
                raise ValueError(f"Ancestor data/protocol identity mismatch: {key}")
        for key, path in (
            ("inference_sha256", paths[2]),
            ("membership_sha256", paths[3]),
            ("review_sha256", paths[5]),
        ):
            if parent.get(key) != sha256(path):
                raise ValueError(f"Ancestor artifact identity mismatch: {key}")
        expected_kind = (
            "SYNTHETIC_CORRECTNESS_ONLY" if correctness_smoke else "REAL_TRAIN_DEVELOPMENT_FIT"
        )
        if (
            parent.get("architecture") != ARCHITECTURE
            or parent_review.get("architecture") != ARCHITECTURE
        ):
            raise ValueError("Ancestor architecture/review differs from band family.")
        if parent.get("status") != "COMPLETED" or parent.get("evidence_kind") != expected_kind:
            raise ValueError("Incomplete or wrong-kind ancestor cannot supply transfer features.")
        membership = _json(paths[3])
        allowed = _split_roles(inputs)["train"]
        deployment, archives = (
            membership.get("train_deployments", []),
            membership.get("train_archive_sha256", []),
        )
        rows = membership.get("train_row_ids", [])
        if (
            not rows
            or len(rows) != len(deployment)
            or len(rows) != len(archives)
            or any(allowed.get(d) != a for d, a in zip(deployment, archives, strict=True))
        ):
            raise ValueError("Ancestor TRAIN source/deployment ancestry mismatch.")
        for name in ("ssl_eligible_indices", "supervised_indices"):
            indices = membership.get(name)
            if (
                not isinstance(indices, list)
                or any(type(i) is not int or not 0 <= i < len(rows) for i in indices)
                or len(set(indices)) != len(indices)
            ):
                raise ValueError("Ancestor membership indices are invalid.")
        for entry in membership.get("sequence", []):
            for name in ("indices", "context_indices", "target_indices"):
                if name in entry and any(
                    type(i) is not int or not 0 <= i < len(rows) for i in entry[name]
                ):
                    raise ValueError("Ancestor sampled membership is outside TRAIN.")
    return review


def _core_config(inputs, config, *, correctness_smoke, smoke_core_config):
    if config.mode == "direct_end_to_end":
        if (
            inputs.encoder is not None
            or inputs.ancestor_review is not None
            or inputs.ancestor_config is not None
        ):
            raise ValueError("Direct initialization must have no selected ancestor.")
        value = (
            smoke_core_config
            if correctness_smoke and smoke_core_config
            else core.Config(method="direct", seed=config.seed, pretrain_updates=3000)
        )
    else:
        if inputs.encoder is None or Path(inputs.encoder).name != "selected_encoder.pt":
            raise ValueError("Transfer requires an exact selected_encoder.pt artifact.")
        raw = _json(Path(inputs.encoder).parent / "run.json")["config"]
        if raw.get("architecture") != ARCHITECTURE:
            raise ValueError("Selected parent config is not the band family.")
        value = core.Config(**raw)
        if smoke_core_config is not None and value.to_dict() != smoke_core_config.to_dict():
            raise ValueError("Smoke architecture differs from selected ancestor.")
        if value.method != config.method or value.history != config.history:
            raise ValueError("Selected ancestor method/history differs from downstream.")
    if value.seed != config.seed:
        raise ValueError("Selected ancestor and downstream seed must match.")
    if not correctness_smoke:
        if smoke_core_config is not None:
            raise ValueError("Small architectures require explicit correctness_smoke.")
        dimensions = core.model_dimensions(value)
        expected = {"width": 192, "latent": 64, "blocks": 4, "heads": 4}
        if dimensions != expected:
            raise ValueError("Real endpoint backbone dimensions are frozen.")
    value.validate(correctness_smoke=correctness_smoke)
    return value


def _parent_core(inputs):
    """Typed source identity is checked before decoding selected parent tensors."""
    parent = _json(Path(inputs.encoder).parent / "run.json")
    bound = parent.get("bindings", {})
    if str(Path(core.__file__).resolve()) in bound:
        return core
    if str(Path(original_core.__file__).resolve()) in bound:
        return original_core
    raise ValueError("Parent must bind its original or replication SSL runner.")


def _load_ancestor(inputs, core_config):
    if inputs.encoder is None:
        return None
    selected = torch.load(inputs.encoder, map_location="cpu", weights_only=True)
    inference = torch.load(
        Path(inputs.encoder).parent / "inference.pt", map_location="cpu", weights_only=True
    )
    parent = _json(Path(inputs.encoder).parent / "run.json")
    original = _parent_core(inputs) is original_core
    selected_kind = (
        "native_band_ssl_selected_encoder_v1"
        if original
        else "native_band_replication_ssl_selected_encoder_v2"
    )
    inference_kind = (
        "native_band_ssl_weights_only_inference_v1"
        if original
        else "native_band_replication_ssl_weights_only_inference_v2"
    )
    if selected.get("kind") != selected_kind or inference.get("kind") != inference_kind:
        raise ValueError("Unsupported selected ancestor artifact kind.")
    for record in (selected, inference):
        if (
            record.get("architecture") != ARCHITECTURE
            or record.get("config") != core_config.to_dict()
            or record.get("bindings") != parent["bindings"]
        ):
            raise ValueError("Selected artifact source/config lineage mismatch.")
    if selected.get("scalers") != inference.get("scalers") or inference.get(
        "selected_pretrain_step"
    ) != parent.get("selected_pretrain_step"):
        raise ValueError("Selected artifact scaler/checkpoint lineage mismatch.")
    # Safe portable loading also validates every full-model tensor and scaler.
    predictor_class = (
        original_inference.NativeBandAcousticPredictor if original else NativeBandAcousticPredictor
    )
    validate_configuration = original_inference._configuration if original else _configuration
    checked = predictor_class.__new__(predictor_class)
    checked._initialize(inference, "cpu")
    validate_configuration(selected, torch.device("cpu"))
    core.Scalers.from_dict(selected.get("scalers"))
    _check_state(selected.get("encoder"), checked.model.encoder.state_dict())
    encoder = {
        k.removeprefix("encoder."): v
        for k, v in inference["model"].items()
        if k.startswith("encoder.")
    }
    if set(encoder) != set(selected["encoder"]) or any(
        not torch.equal(v, encoder[k]) for k, v in selected["encoder"].items()
    ):
        raise ValueError("Selected encoder differs from parent inference features.")
    return selected


def prepare_model(config, core_config, selected):
    """Fresh heads always use seed+100000, independently of pretraining RNG."""
    model = core.initialize_model(
        config.seed, **core.model_dimensions(core_config), method=config.method
    )
    if selected is not None:
        model.encoder.load_state_dict(selected["encoder"], strict=True)
    model.requires_grad_(False)
    model.readout.requires_grad_(True)
    if config.mode != "frozen_readout":
        model.encoder.requires_grad_(True)
    model.encoder.eval()
    return model


def supervised_indices(pool, config, step):
    return core.batch_indices(pool, config.batch_size, config.seed, "readout", step)


def _forecast_train(model, batch, mode):
    # Only the selected shared band features receive separate supervised gradients.
    # Frozen mode uses eval/no_grad; no EMA update or SSL loss occurs here.
    model.readout.train()
    if mode == "frozen_readout":
        model.encoder.eval()
        with torch.no_grad():
            features = model.encoder.encode(batch["x"], batch["observed"], batch["metadata"])
    else:
        model.encoder.train()
        features = model.encoder.encode(batch["x"], batch["observed"], batch["metadata"])
    return model.readout(features, batch["query"]).sort(dim=-1).values


def _verify_data(inputs, train, dev, selected):
    for role, data in (("train", train), ("development", dev)):
        core.validate_membership(data, inputs.split, role=role)
        cohort = _cohort(inputs, role)
        reports = cohort.get("source_reports", [])
        counts = {
            str(d): int((data["deployment"] == d).sum()) for d in np.unique(data["deployment"])
        }
        if (
            cohort.get("issued") != len(data["x"])
            or {r["deployment"]: r["issued"] for r in reports if r["issued"]} != counts
        ):
            raise ValueError("Cohort issued/source counts mismatch.")
    if set(train["row_id"].tolist()) & set(dev["row_id"].tolist()):
        raise ValueError("TRAIN/development row membership overlaps.")
    fitted = core.Scalers.fit(train, split_path=inputs.split)
    if selected is None:
        return fitted
    membership = _json(Path(inputs.encoder).parent / "membership.json")
    for name, key in (
        ("train_row_ids", "row_id"),
        ("train_deployments", "deployment"),
        ("train_archive_sha256", "archive_sha256"),
    ):
        if membership[name] != train[key].tolist():
            raise ValueError("Ancestor exact TRAIN row/source membership mismatch.")
    for name, indices in (
        ("ssl_eligible_indices", np.flatnonzero(train["ssl_eligible"])),
        ("supervised_indices", np.flatnonzero(train["y_observed"].any(1))),
    ):
        if membership[name] != indices.tolist():
            raise ValueError("Ancestor TRAIN eligibility membership mismatch.")
    # Recompute TRAIN statistics only to verify lineage, never replace ancestor
    # scalers and never fit development. Comparison is exact float32/list state.
    if selected["scalers"] != fitted.to_dict():
        raise ValueError("Ancestor scalers are not fitted exclusively to this TRAIN.")
    return core.Scalers.from_dict(selected["scalers"])


def _safe_cpu(value):
    if isinstance(value, torch.Tensor):
        return value.detach().cpu().clone()
    if isinstance(value, dict):
        return {k: _safe_cpu(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_safe_cpu(v) for v in value]
    if isinstance(value, tuple):
        return tuple(_safe_cpu(v) for v in value)
    return copy.deepcopy(value)


def _verify_continuation(saved, config, pool, train, scalers):
    state = saved["state"]
    if state["scalers"] != scalers.to_dict():
        raise ValueError("Resume scaler identity differs from TRAIN lineage.")
    step = state.get("step")
    if type(step) is not int or not 0 <= step <= config.updates or len(state["sequence"]) != step:
        raise ValueError("Resume sampler counters differ from supervised trajectory.")
    if saved["scheduler"].get("last_epoch") != step:
        raise ValueError("Resume schedule differs from supervised counters.")
    for index, entry in enumerate(state["sequence"]):
        ids = supervised_indices(pool, config, index)
        if entry != {
            "step": index,
            "indices": ids.tolist(),
            "row_ids": train["row_id"][ids].tolist(),
            "sha256": core.sequence_hash(ids),
        }:
            raise ValueError(
                "Resume sampler sequence differs from independent seed-controlled TRAIN batches."
            )
    records = state["records"]
    expected = [s for s in range(1, step + 1) if s % config.cadence == 0 or s == config.updates]
    if [r["step"] for r in records] != expected:
        raise ValueError("Resume checkpoint selection cadence differs.")
    best_score, best_step, bad_checks = None, None, 0
    for record in records:
        score = record["daily_dev_pinball"]
        if not isinstance(score, (int, float)) or not np.isfinite(score):
            raise ValueError("Resume selection score is invalid.")
        improved = best_score is None or score < best_score
        if record["selected"] != improved:
            raise ValueError("Resume checkpoint selection record differs.")
        if improved:
            best_score, best_step, bad_checks = score, record["step"], 0
        else:
            bad_checks += 1
    if (state["best_score"], state["best_step"], state["bad_checks"], state["stopped"]) != (
        best_score,
        best_step,
        bad_checks,
        bad_checks >= config.patience,
    ) or (state["best_model"] is None) != (best_step is None):
        raise ValueError("Resume best checkpoint/stopping counters differ.")


def run(
    inputs,
    config,
    *,
    output,
    device="cpu",
    resume=None,
    correctness_smoke=False,
    smoke_core_config=None,
    stop_after=None,
):
    config.validate(correctness_smoke=correctness_smoke)
    device = torch.device(device)
    if not correctness_smoke and str(device) != "cuda:0":
        raise ValueError("Scientific replication requires explicitly indexed cuda:0.")
    if device.type not in ("cpu", "cuda") or (correctness_smoke and device.type != "cpu"):
        raise ValueError("Correctness smoke is CPU only; endpoints support local CPU/CUDA only.")
    if stop_after is not None and (not correctness_smoke or stop_after < 1):
        raise ValueError("Artificial interruption is reserved for CPU correctness checks.")
    ancestor_config = _core_config(
        inputs, config, correctness_smoke=correctness_smoke, smoke_core_config=smoke_core_config
    )
    review = check_prefit(inputs, config, ancestor_config, correctness_smoke=correctness_smoke)
    identities = {
        "bindings": {str(p): sha256(p) for p in required_paths(inputs, ancestor_config)},
        "review_sha256": sha256(inputs.review),
        "config": config.to_dict(),
        "core_config": ancestor_config.to_dict(),
        "device_kind": device.type,
        "evidence_kind": "SYNTHETIC_CORRECTNESS_ONLY"
        if correctness_smoke
        else "REAL_TRAIN_DEVELOPMENT_FIT",
    }
    saved = None
    if resume is not None:
        saved = torch.load(resume, map_location="cpu", weights_only=True)
        if (
            saved.get("kind") != "native_band_replication_downstream_resume_v2"
            or saved.get("architecture") != ARCHITECTURE
            or saved.get("identities") != identities
        ):
            raise ValueError("Resume source/config/review/ancestor/device identities differ.")
    output = Path(output).resolve()
    if output.exists():
        if (
            resume is None
            or Path(resume).resolve().parent != output
            or Path(resume).name != "latest.pt"
        ):
            raise ValueError("Existing outputs require explicit same-run latest.pt resume.")
        if (output / "run.json").exists():
            raise ValueError("Completed outputs cannot be overwritten or silently extended.")
    # Refuse a nonempty directory even with filesystem transports that do not
    # represent directories separately; normal output directories are created below.
    try:
        nonempty = bool(list(output.iterdir()))
    except FileNotFoundError:
        nonempty = False
    if nonempty and (resume is None or Path(resume).resolve().parent != output):
        raise ValueError("New output path must be empty; no silent overwrite.")
    selected = _load_ancestor(inputs, ancestor_config)
    train = core.load_corpus(
        inputs.train,
        role="train",
        split_hash=sha256(inputs.split),
        correctness_smoke=correctness_smoke,
    )
    dev = core.load_corpus(
        inputs.dev,
        role="development",
        split_hash=sha256(inputs.split),
        correctness_smoke=correctness_smoke,
    )
    scalers = _verify_data(inputs, train, dev, selected)
    pool = np.flatnonzero(train["y_observed"].any(1))
    if not len(pool):
        raise ValueError("No observed TRAIN supervised rows.")
    if saved is not None:
        _verify_continuation(saved, config, pool, train, scalers)
    inference_config = replace(
        ancestor_config,
        method=config.method,
        seed=config.seed,
        history=config.history,
        batch_size=config.batch_size,
        lr=config.lr,
        weight_decay=config.weight_decay,
    )
    random.seed(config.seed)
    np.random.seed(config.seed)
    torch.manual_seed(config.seed)
    model = prepare_model(config, ancestor_config, selected)
    frozen_state = core.cpu_state(model.encoder) if config.mode == "frozen_readout" else None
    if saved is not None:
        _check_state(saved["model"], model.state_dict())
        model.load_state_dict(saved["model"], strict=True)
        if frozen_state is not None:
            for candidate in (saved["model"], saved["state"]["best_model"]):
                if candidate is not None and any(
                    not torch.equal(v, candidate["encoder." + k]) for k, v in frozen_state.items()
                ):
                    raise ValueError("Frozen resume encoder differs from selected ancestor.")
    parameters = [p for p in model.parameters() if p.requires_grad]
    state = {
        "step": 0,
        "best_step": None,
        "best_score": None,
        "best_model": None,
        "bad_checks": 0,
        "sequence": [],
        "records": [],
        "scalers": scalers.to_dict(),
        "stopped": False,
    }
    output.mkdir(parents=True, exist_ok=True)
    with core.Resources(device, output) as resources:
        model.to(device)
        if device.type == "cuda":
            torch.cuda.manual_seed_all(config.seed)
        optimizer = torch.optim.AdamW(parameters, lr=config.lr, weight_decay=config.weight_decay)
        scheduler = core.schedule(optimizer, config.updates)
        if saved is not None:
            state = saved["state"]
            optimizer.load_state_dict(saved["optimizer"])
            scheduler.load_state_dict(saved["scheduler"])
            for item in optimizer.state.values():
                for key, value in item.items():
                    if isinstance(value, torch.Tensor):
                        item[key] = value.to(device)
            core.restore_rng(saved["rng"])
            resources.elapsed = saved["resources"]["elapsed_seconds"]
            resources.peak_rss = saved["resources"]["peak_rss_bytes"]
            resources.peak_allocated = saved["resources"]["peak_allocated_bytes"]
            resources.peak_reserved = saved["resources"]["peak_reserved_bytes"]

        def save(name="latest.pt"):
            payload = {
                "kind": "native_band_replication_downstream_resume_v2",
                "architecture": ARCHITECTURE,
                "correctness_smoke": correctness_smoke,
                "identities": identities,
                "state": _safe_cpu(state),
                "model": core.cpu_state(model),
                "optimizer": _safe_cpu(optimizer.state_dict()),
                "scheduler": scheduler.state_dict(),
                "rng": core.rng_state(),
                "resources": resources.snapshot(),
            }
            core.atomic_checkpoint(output / name, payload)
            if name != "latest.pt":
                core.atomic_checkpoint(output / "latest.pt", payload)

        while state["step"] < config.updates and not state["stopped"]:
            ids = supervised_indices(pool, config, state["step"])
            batch = core.tensor_batch(train, ids, scalers, config.history, device)
            optimizer.zero_grad(set_to_none=True)
            predictions = _forecast_train(model, batch, config.mode)
            loss = core.pinball(predictions, batch["y"], batch["y_observed"])
            if not torch.isfinite(loss):
                raise RuntimeError("Nonfinite downstream loss.")
            loss.backward()
            torch.nn.utils.clip_grad_norm_(
                parameters, config.gradient_clip, error_if_nonfinite=True
            )
            optimizer.step()
            scheduler.step()
            state["sequence"].append(
                {
                    "step": state["step"],
                    "indices": ids.tolist(),
                    "row_ids": train["row_id"][ids].tolist(),
                    "sha256": core.sequence_hash(ids),
                }
            )
            state["step"] += 1
            resources.check()
            if frozen_state is not None and any(
                not torch.equal(v, model.encoder.state_dict()[k].detach().cpu())
                for k, v in frozen_state.items()
            ):
                raise RuntimeError("Frozen encoder parameters/buffers changed.")
            if state["step"] % config.cadence == 0 or state["step"] == config.updates:
                values = core.predict(model, dev, scalers, inference_config, device)
                metrics = core.daily_metrics(
                    values,
                    dev["y"],
                    dev["y_observed"],
                    dev["target_dates"],
                    dev["deployment"],
                    min_anchors=config.min_daily_anchors,
                )
                score = metrics["primary_pinball"]
                if score is None:
                    raise ValueError(
                        "Development has insufficient shared native daily support for selection."
                    )
                improved = state["best_score"] is None or score < state["best_score"]
                if improved:
                    state.update(
                        best_score=score,
                        best_step=state["step"],
                        best_model=core.cpu_state(model),
                        bad_checks=0,
                    )
                else:
                    state["bad_checks"] += 1
                state["records"].append(
                    {"step": state["step"], "daily_dev_pinball": score, "selected": improved}
                )
                state["stopped"] = state["bad_checks"] >= config.patience
                save(f"supervised-{state['step']:06d}.pt")
            if stop_after is not None and state["step"] >= stop_after:
                save()
                return {
                    "status": "INTERRUPTED_CORRECTNESS_CHECK",
                    "supervised_updates": state["step"],
                }
        if state["best_model"] is None:
            raise ValueError("No selected downstream checkpoint.")
        save("complete.pt")
        model.load_state_dict(state["best_model"], strict=True)
        model.eval()
        model.requires_grad_(False)
        bindings = identities["bindings"]
        ancestry = {
            "mode": config.mode,
            "ssl_only": False,
            "supervised_updates": state["step"],
            "selected_supervised_step": state["best_step"],
            "ancestor_encoder_sha256": sha256(inputs.encoder) if inputs.encoder else None,
            "ancestor_run_sha256": sha256(Path(inputs.encoder).parent / "run.json")
            if inputs.encoder
            else None,
        }
        inference = {
            "kind": "native_band_replication_ssl_weights_only_inference_v2",
            "architecture": ARCHITECTURE,
            "correctness_smoke": correctness_smoke,
            "model": core.cpu_state(model),
            "config": inference_config.to_dict(),
            "scalers": scalers.to_dict(),
            "bindings": bindings,
            "downstream_config": config.to_dict(),
            "supervised_ancestry": ancestry,
            "review_sha256": identities["review_sha256"],
            "evidence_kind": identities["evidence_kind"],
        }
        core.atomic_checkpoint(output / "inference.pt", inference)
        if config.mode == "frozen_readout":
            # Byte identity matters: reserializing the same tensors is insufficient.
            with (output / "selected_encoder.pt").open("xb") as stream:
                stream.write(Path(inputs.encoder).read_bytes())
        else:
            core.atomic_checkpoint(
                output / "selected_encoder.pt",
                {
                    "kind": "native_band_replication_downstream_supervised_encoder_v2",
                    "architecture": ARCHITECTURE,
                    "correctness_smoke": correctness_smoke,
                    "encoder": core.cpu_state(model.encoder),
                    "config": inference_config.to_dict(),
                    "scalers": scalers.to_dict(),
                    "bindings": bindings,
                    "supervised_ancestry": ancestry,
                    "evidence_kind": identities["evidence_kind"],
                },
            )
        values = core.predict(model, dev, scalers, inference_config, device)
        np.savez_compressed(
            output / "predictions.npz",
            predictions=values,
            targets=dev["y"],
            target_observed=dev["y_observed"],
            target_dates=dev["target_dates"],
            row_id=dev["row_id"],
            deployment=dev["deployment"],
            archive_sha256=dev["archive_sha256"],
            cutoff=dev["cutoff"],
            query=dev["query"],
            metadata=dev["metadata"],
            context_observed=dev["observed"],
            assessment_support=np.ones_like(dev["y_observed"]),
            query_native_bounds_m=dev["query"][:, :, 3:5] * 250,
            query_frequency_hz=dev["query"][:, :, 0] * 455000,
            query_interval_seconds=dev["query"][:, :, 1] * 3600,
            quantiles=np.asarray(core.QUANTILES),
            horizons=np.asarray([1, 3, 6]),
        )
        metrics = core.daily_metrics(
            values,
            dev["y"],
            dev["y_observed"],
            dev["target_dates"],
            dev["deployment"],
            min_anchors=config.min_daily_anchors,
        )
        _write_json(output / "metrics.json", metrics)
        sequence = state["sequence"]
        membership = {
            "train_row_ids": train["row_id"].tolist(),
            "train_deployments": train["deployment"].tolist(),
            "train_archive_sha256": train["archive_sha256"].tolist(),
            "supervised_indices": pool.tolist(),
            "sequence": sequence,
            "sequence_sha256": hashlib.sha256(
                json.dumps(sequence, sort_keys=True, separators=(",", ":")).encode()
            ).hexdigest(),
        }
        _write_json(output / "membership.json", membership)
        report = {
            "architecture": ARCHITECTURE,
            "correctness_smoke": correctness_smoke,
            "status": "COMPLETED",
            "evidence_kind": identities["evidence_kind"],
            "mode": config.mode,
            "config": config.to_dict(),
            "core_config": inference_config.to_dict(),
            "supervised_updates": state["step"],
            "optimizer_steps_total": state["step"],
            "selected_supervised_step": state["best_step"],
            "label_observations_processed": int(
                sum(train["y_observed"][entry["indices"]].sum() for entry in sequence)
            ),
            "sample_presentations": sum(len(entry["indices"]) for entry in sequence),
            "parameters_total": sum(p.numel() for p in model.parameters()),
            "parameters_optimized": sum(p.numel() for p in parameters),
            "parameters_encoder": sum(p.numel() for p in model.encoder.parameters()),
            "parameters_head": sum(p.numel() for p in model.readout.parameters()),
            "resources_additional_downstream": resources.snapshot(),
            "selection_records": state["records"],
            "selected_daily_dev_pinball": state["best_score"],
            "bindings": bindings,
            "review_sha256": identities["review_sha256"],
            "reviewer_session_id": review["reviewer_session_id"],
            "membership_sha256": sha256(output / "membership.json"),
            "inference_sha256": sha256(output / "inference.pt"),
            "selected_encoder_sha256": sha256(output / "selected_encoder.pt"),
            "supervised_ancestry": ancestry,
            "initialization": "fresh_seed_controlled_head_and_selected_features"
            if selected
            else "matched_seed_controlled_random_model_and_head",
            "selection_policy": config.selection_policy,
            "stopping_patience": config.patience,
            "test_access": "NOT_RUN",
            "scientific_claim": "NOT_ESTABLISHED",
        }
        _write_json(output / "run.json", report)
        return report


class Inference(NativeBandAcousticPredictor):
    """Safe, frozen target-free endpoint loader without fit initialization."""

    def __init__(self, artifact, device):
        self._initialize(artifact, device)


def load_inference(path, *, device="cpu"):
    return Inference(torch.load(path, map_location="cpu", weights_only=True), device)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    for flag in (
        "train",
        "dev",
        "train-cohort",
        "dev-cohort",
        "split",
        "adr0016",
        "protocol",
        "config",
        "review",
        "output",
    ):
        parser.add_argument(f"--{flag}", required=True, type=Path)
    for flag in ("encoder", "ancestor-review", "ancestor-config", "resume"):
        parser.add_argument(f"--{flag}", type=Path)
    parser.add_argument("--device", default="cpu", choices=("cpu", "cuda:0"))
    args = parser.parse_args(argv)
    config = DownstreamConfig(**_json(args.config))
    inputs = RunInputs(**{name: getattr(args, name) for name in RunInputs.__dataclass_fields__})
    report = run(inputs, config, output=args.output, device=args.device, resume=args.resume)
    print(
        json.dumps(
            {
                key: report[key]
                for key in ("status", "mode", "supervised_updates", "inference_sha256")
            }
        )
    )


if __name__ == "__main__":
    main()

src/marine_echo/inference/native_band_re.text:
"""Safe target-free inference for the separate nonlinear band family.

Frozen source ancestry is exposed, never opened or executed. Meta constructors
consume no CPU RNG and initialize no optimizer, determinism policy or disk cache.
Native inputs retain their actual sensing geometry; embeddings are not profiles.
"""

from __future__ import annotations

import copy
import math
from collections.abc import Mapping
from dataclasses import fields

import numpy as np
import torch

from marine_echo.inference import native_encoder as legacy
from marine_echo.models.native_band_temporal import (
    ARCHITECTURE,
    NativeBandEncoder,
    NativeBandTemporalModel,
)
from marine_echo.training.native_band_replication_ssl import METHODS, Config

TRAINING_KINDS = {key: value for key, value in legacy.TRAINING_KINDS.items() if key in METHODS}
SELECTED_KIND = "native_band_replication_ssl_selected_encoder_v2"
INFERENCE_KIND = "native_band_replication_ssl_weights_only_inference_v2"


def _configuration(artifact, device):
    raw = artifact.get("config")
    if (
        artifact.get("architecture") != ARCHITECTURE
        or not isinstance(raw, dict)
        or raw.get("architecture") != ARCHITECTURE
        or raw.get("method") not in METHODS
    ):
        raise ValueError("Exact band architecture/config required; legacy and CF are unsupported.")
    expected = {field.name: field.default for field in fields(Config)}
    if set(raw) != set(expected):
        raise ValueError("Complete exact saved replication Config required.")
    for key, default in expected.items():
        value = raw[key]
        if type(default) is int:
            if type(value) is not int or value < 0:
                raise ValueError("Invalid saved integer configuration.")
        elif type(default) is float:
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(value)
            ):
                raise ValueError("Nonfinite or incompatible saved configuration.")
        elif not isinstance(value, str) or not value:
            raise ValueError("Invalid saved string configuration.")
    if (
        not 1 <= raw["batch_size"] <= 256
        or max(raw["width"], raw["latent"]) > 512
        or max(raw["blocks"], raw["heads"]) > 16
    ):
        raise ValueError("Saved inference dimensions must remain bounded.")
    for key in ("seed", "history", "batch_size", "width", "latent", "blocks", "heads"):
        if type(raw.get(key)) is not int or raw[key] < (0 if key == "seed" else 1):
            raise ValueError(f"Explicit compatible saved dimension/config required: {key}")
    try:
        config = Config(**raw)
    except TypeError as error:
        raise ValueError("Incompatible band Config fields.") from error
    if config.history != 96 or config.width % config.heads:
        raise ValueError("Band inference requires H96 and valid attention dimensions.")
    smoke = artifact.get("evidence_kind") == "SYNTHETIC_CORRECTNESS_ONLY"
    if smoke and (device.type != "cpu" or artifact.get("correctness_smoke") is not True):
        raise ValueError("Tiny correctness artifacts require explicit synthetic CPU identity.")
    if not smoke and artifact.get("evidence_kind") != "REAL_TRAIN_DEVELOPMENT_FIT":
        raise ValueError("Saved band evidence kind is missing or incompatible.")
    if config.seed not in (7, 13, 23):
        raise ValueError("Band replication seed must be exactly7/13/23.")
    if not smoke and (config.width, config.latent, config.blocks, config.heads) != (
        192,
        64,
        4,
        4,
    ):
        raise ValueError("Scientific band dimensions/seed are frozen.")
    config.validate(correctness_smoke=smoke)
    return config


def _check_state(state, expected):
    if not isinstance(state, Mapping) or set(state) != set(expected):
        raise ValueError("Safe state must contain exactly the required tensors/buffers.")
    for key, template in expected.items():
        value = state[key]
        if (
            not isinstance(value, torch.Tensor)
            or value.layout != torch.strided
            or value.device.type != "cpu"
            or value.shape != template.shape
            or value.dtype != template.dtype
            or not torch.isfinite(value).all()
        ):
            raise ValueError(f"Incompatible or nonfinite safe tensor: {key}")


def _base(instance, artifact, device):
    if not isinstance(artifact, Mapping):
        raise TypeError("Expected a safe band artifact mapping.")
    allowed = {
        "kind",
        "architecture",
        "config",
        "scalers",
        "bindings",
        "encoder",
        "model",
        "evidence_kind",
        "correctness_smoke",
        "selected_pretrain_step",
        "downstream_config",
        "supervised_ancestry",
    }
    if not set(artifact).issubset(allowed):
        raise ValueError("Unknown or unsafe fields in replication inference artifact.")
    if (artifact.get("kind") == INFERENCE_KIND and "encoder" in artifact) or (
        artifact.get("kind") == SELECTED_KIND
        and (
            "model" in artifact
            or "supervised_ancestry" in artifact
            or "downstream_config" in artifact
        )
    ):
        raise ValueError("Artifact contains incompatible branch or supervised state.")
    if str(device) not in ("cpu", "cuda:0"):
        raise ValueError("Device must be explicitly cpu or cuda:0.")
    instance.device = torch.device(device)
    if instance.device.type not in ("cpu", "cuda"):
        raise ValueError("Only local CPU/CUDA devices are supported.")
    instance.config = _configuration(artifact, instance.device)
    instance.scalers = legacy._scalers(artifact.get("scalers"))
    instance._bindings = legacy._bindings(artifact.get("bindings"))
    instance._config_metadata = copy.deepcopy(artifact["config"])
    instance._scaler_metadata = copy.deepcopy(artifact["scalers"])
    instance.method = instance.config.method
    instance.architecture = ARCHITECTURE
    instance.training_kind = TRAINING_KINDS[instance.method]
    instance.embedding_dimension = instance.config.latent


class NativeBandAcousticEncoder(legacy.NativeAcousticEncoder):
    """Selected shared-band encoder only; no query, readout, targets or future.

    Separately supervised selected encoders are explicitly unsupported here.
    Issuance/source-clock association remains the caller's responsibility.
    """

    def __init__(self, weights, device="cpu"):
        artifact = torch.load(weights, map_location="cpu", weights_only=True)
        if not isinstance(artifact, Mapping) or artifact.get("kind") != SELECTED_KIND:
            raise ValueError("Expected native_band_replication_ssl_selected_encoder_v2 only.")
        _base(self, artifact, device)
        self.feature_branch = "shared_band_encoder"
        self.selected_pretrain_step = artifact.get("selected_pretrain_step")
        if self.selected_pretrain_step is not None and (
            type(self.selected_pretrain_step) is not int or self.selected_pretrain_step < 0
        ):
            raise ValueError("Optional selected step must be a nonnegative integer.")
        with torch.device("meta"):
            encoder = NativeBandEncoder(
                self.config.width, self.config.latent, self.config.blocks, self.config.heads
            ).float()
        _check_state(artifact.get("encoder"), encoder.state_dict())
        encoder.load_state_dict(artifact["encoder"], strict=True, assign=True)
        self.encoder = encoder.eval().requires_grad_(False).to(self.device)


def _query(query, metadata):
    query = np.asarray(query)
    if (
        query.shape != (len(metadata), 3, 10)
        or query.dtype.kind != "f"
        or not np.isfinite(query).all()
        or not np.allclose(query[..., :9], metadata[:, :1, :9], rtol=0, atol=1e-6)
        or not np.allclose(query[..., 9], [1, 3, 6], rtol=0, atol=1e-6)
    ):
        raise ValueError("Issued query must retain primary native fields and horizons1/3/6.")
    with np.errstate(over="ignore", invalid="ignore"):
        result = query.astype(np.float32, copy=False)
    if not np.isfinite(result).all() or (result[..., 4] <= result[..., 3]).any():
        raise ValueError("Issued native query must remain finite/valid at model precision.")
    return result


def _ancestry(artifact, config):
    ancestry = artifact.get("supervised_ancestry")
    if ancestry is None:
        if "downstream_config" in artifact:
            raise ValueError("Downstream forecast requires explicit supervised ancestry.")
        return None
    from marine_echo.training.native_band_replication_downstream import DownstreamConfig

    if not isinstance(ancestry, dict) or not isinstance(artifact.get("downstream_config"), dict):
        raise TypeError("Complete supervised ancestry/config is required.")
    try:
        downstream = DownstreamConfig(**artifact["downstream_config"])
    except TypeError as error:
        raise ValueError("Incompatible downstream config.") from error
    downstream.validate(correctness_smoke=artifact.get("correctness_smoke") is True)
    for key in ("method", "seed", "history", "batch_size", "lr", "weight_decay", "architecture"):
        if getattr(downstream, key) != getattr(config, key):
            raise ValueError("Downstream inference config differs from its supervised ancestry.")
    steps, selected = ancestry.get("supervised_updates"), ancestry.get("selected_supervised_step")
    if (
        ancestry.get("mode") != downstream.mode
        or ancestry.get("ssl_only") is not False
        or type(steps) is not int
        or not 1 <= steps <= downstream.updates
        or type(selected) is not int
        or not 1 <= selected <= steps
    ):
        raise ValueError("Invalid supervised update/selection ancestry.")
    for key in ("ancestor_encoder_sha256", "ancestor_run_sha256"):
        value = ancestry.get(key)
        if downstream.mode == "direct_end_to_end":
            if value is not None:
                raise ValueError("Direct endpoint must have no selected ancestor.")
        elif (
            not isinstance(value, str)
            or len(value) != 64
            or any(c not in "0123456789abcdef" for c in value)
        ):
            raise ValueError("Transferred inference requires exact ancestor identities.")
    return copy.deepcopy(ancestry)


class NativeBandAcousticPredictor:
    """Safe band forecast plus reusable encoding, including downstream forecasts."""

    def __init__(self, weights, *, device="cpu"):
        self._initialize(torch.load(weights, map_location="cpu", weights_only=True), device)

    def _initialize(self, artifact, device):
        if not isinstance(artifact, Mapping) or artifact.get("kind") != INFERENCE_KIND:
            raise ValueError("Expected native_band_replication_ssl_weights_only_inference_v2 only.")
        _base(self, artifact, device)
        self.feature_training_kind = self.training_kind
        self.supervised_ancestry = _ancestry(artifact, self.config)
        if self.supervised_ancestry is not None:
            mode = self.supervised_ancestry["mode"]
            self.training_kind = "supervised_downstream_" + mode
            if mode != "frozen_readout":
                self.feature_training_kind = "supervised_feature_encoder"
        else:
            self.training_kind = "train_fitted_readout_on_" + self.feature_training_kind
        with torch.device("meta"):
            model = NativeBandTemporalModel(
                self.config.width, self.config.latent, self.config.blocks, self.config.heads
            ).float()
        _check_state(artifact.get("model"), model.state_dict())
        model.load_state_dict(artifact["model"], strict=True, assign=True)
        self.model = model.eval().requires_grad_(False).to(self.device)
        self.encoder = self.model.encoder

    @property
    def config_metadata(self):
        return copy.deepcopy(self._config_metadata)

    @property
    def scaler_metadata(self):
        return copy.deepcopy(self._scaler_metadata)

    @property
    def source_bindings(self):
        return copy.deepcopy(self._bindings)

    @torch.inference_mode()
    def encode(self, x, observed, metadata):
        # Inherited encoder-only implementation validates raw native inputs and
        # batches with saved scalers. It never requires the readout/query path.
        return legacy.NativeAcousticEncoder.encode(self, x, observed, metadata)

    @torch.inference_mode()
    def forecast(self, x, observed, metadata, query):
        x, observed, metadata = legacy._inputs(x, observed, metadata, self.config.history)
        query = _query(query, metadata)
        self.model.eval()
        result = []
        for start in range(0, len(x), self.config.batch_size):
            end = min(start + self.config.batch_size, len(x))
            with np.errstate(over="ignore", invalid="ignore"):
                values = self.scalers.channels(x[start:end], observed[start:end])
            if not np.isfinite(values).all():
                raise ValueError("Observed scaled dB must be finite at model precision.")
            prediction = (
                self.model.forecast(
                    torch.as_tensor(values, device=self.device),
                    torch.as_tensor(observed[start:end].copy(order="C"), device=self.device),
                    torch.as_tensor(metadata[start:end].copy(order="C"), device=self.device),
                    torch.as_tensor(query[start:end].copy(order="C"), device=self.device),
                )
                .cpu()
                .numpy()
            )
            prediction = (
                prediction * self.scalers.target_std[None, :, None]
                + self.scalers.target_mean[None, :, None]
            )
            if prediction.shape != (end - start, 3, 5) or not np.isfinite(prediction).all():
                raise ValueError("Forecast output must be finite native dB [N,3,5].")
            result.append(prediction)
        return np.concatenate(result)


def load_inference(weights, *, device="cpu"):
    return NativeBandAcousticPredictor(weights, device=device)

"""Load-only access to native SSL embeddings and trained forward latent heads.

Shared predictions represent four-interval future blocks at source offsets1/3/6.
CF predicts three ordinal future zones from ONLINE sequence features, while
encode returns SELECTED EMA pooled features. Full H96 CF inference is outside
its sampled crop-view support. Neither output is acoustic dB or a depth profile.
Ancestral paths are copied metadata, never opened, imported or executed.
"""

from __future__ import annotations

import copy
import math
from collections.abc import Mapping
from dataclasses import fields

import numpy as np
import torch
from torch import nn

from marine_echo.inference import native_encoder as legacy
from marine_echo.inference.native_band_replication_acoustic import _check_state, _query
from marine_echo.models.native_band_temporal import ARCHITECTURE, NativeBandTemporalModel
from marine_echo.models.native_temporal import (
    CFTemporalEncoder,
    NativeTemporalModel,
    QueryHead,
)
from marine_echo.training.native_band_replication_ssl import Config as BandConfig
from marine_echo.training.native_ssl import Config

LEGACY_KIND = "native_ssl_weights_only_inference_v1"
BAND_KIND = "native_band_replication_ssl_weights_only_inference_v2"
LATENT_METHODS = {"shared_ssl", "permuted_ssl", "cf_jepa"}


class _LoadOnlyCF(nn.Module):
    """Exact CF state layout without stochastic predictor re-initialization.

    No CF training initializer, loss, EMA update or optimizer is constructed.
    All modules are empty meta templates until strict tensor assignment.
    """

    def __init__(self, config):
        super().__init__()
        dims = (config.cf_width, config.cf_latent, config.cf_blocks)
        self.online = CFTemporalEncoder(*dims)
        self.encoder = CFTemporalEncoder(*dims)
        self.readout = QueryHead(config.cf_latent, 5, config.cf_latent)
        self.predictors = nn.ModuleList(
            [nn.Linear(config.cf_latent, config.cf_latent) for _ in range(3)]
        )


def _configuration(artifact, device, band):
    raw = artifact.get("config")
    cls = BandConfig if band else Config
    expected = {f.name: f.default for f in fields(cls)}
    if not isinstance(raw, dict) or set(raw) != set(expected):
        raise ValueError("Complete exact saved Config fields required; no inferred defaults.")
    for key, default in expected.items():
        value = raw[key]
        if type(default) is int:
            if type(value) is not int or value < 0:
                raise ValueError(f"Invalid saved integer config: {key}")
        elif type(default) is float:
            if (
                isinstance(value, bool)
                or not isinstance(value, (int, float))
                or not math.isfinite(value)
            ):
                raise ValueError(f"Nonfinite/incompatible saved numeric config: {key}")
            if value < 0:
                raise ValueError(f"Negative saved numeric config: {key}")
        elif not isinstance(value, str) or not value:
            raise ValueError(f"Invalid saved string config: {key}")
    if raw["method"] not in legacy.TRAINING_KINDS or (band and raw["method"] == "cf_jepa"):
        raise ValueError("Unknown/incompatible method for the exact artifact family.")
    if band:
        if raw["architecture"] != ARCHITECTURE or artifact.get("architecture") != ARCHITECTURE:
            raise ValueError("Exact separate band architecture required.")
    elif "architecture" in artifact:
        raise ValueError("Legacy artifacts do not declare or reinterpret band architecture.")
    if raw["history"] != 96 or not 1 <= raw["batch_size"] <= 256:
        raise ValueError("Latent inference requires saved H96 and bounded batch size.")
    for key in ("width", "latent", "cf_width", "cf_latent"):
        if not 1 <= raw[key] <= 512:
            raise ValueError("Saved width/latent dimensions are missing or unbounded.")
    for key in ("blocks", "cf_blocks", "heads"):
        if not 1 <= raw[key] <= 16:
            raise ValueError("Saved block/head dimensions are missing or unbounded.")
    if raw["width"] % raw["heads"] or raw["lr"] <= 0 or raw["cf_lr"] <= 0:
        raise ValueError("Incompatible saved dimensions/numeric configuration.")
    evidence = artifact.get("evidence_kind")
    smoke = evidence == "SYNTHETIC_CORRECTNESS_ONLY"
    if smoke:
        if artifact.get("correctness_smoke") is not True or device.type != "cpu":
            raise ValueError("Tiny fixtures require explicitly synthetic CPU correctness identity.")
    elif evidence not in (None, "REAL_TRAIN_DEVELOPMENT_FIT") or artifact.get(
        "correctness_smoke"
    ) not in (None, False):
        raise ValueError("Unknown/inconsistent artifact evidence kind.")
    if band and evidence is None:
        raise ValueError("Band artifact evidence identity is required.")
    if not smoke:
        if raw["method"] == "cf_jepa":
            if (raw["cf_width"], raw["cf_latent"], raw["cf_blocks"]) != (256, 128, 5):
                raise ValueError("Real CF encoder dimensions must match the native contract.")
        elif (raw["width"], raw["latent"], raw["blocks"], raw["heads"]) not in (
            (192, 64, 4, 4),
            (192, 128, 4, 4),
        ):
            raise ValueError("Tiny dimensions require SYNTHETIC_CORRECTNESS_ONLY.")
        if band and (raw["seed"] not in (7, 13, 23) or raw["latent"] != 64):
            raise ValueError("Band scientific architecture is separate and frozen.")
    # Structural inference validation only, never Config.validate/fit policy.
    return cls(**raw) if band else legacy._config(raw)


def _artifact(artifact, device):
    if not isinstance(artifact, Mapping) or artifact.get("kind") != BAND_KIND:
        raise ValueError("Only original/band SSL weights-only inference artifacts are supported.")
    allowed = {
        "kind",
        "model",
        "config",
        "scalers",
        "bindings",
        "selected_pretrain_step",
        "evidence_kind",
        "correctness_smoke",
    }
    band = artifact["kind"] == BAND_KIND
    if band:
        allowed.add("architecture")
    if not set(artifact).issubset(allowed):
        raise ValueError("Unsafe/unknown fields or downstream supervised ancestry are unsupported.")
    config = _configuration(artifact, device, band)
    if config.seed not in (7, 13, 23):
        raise ValueError("Band replication seed must be exactly7/13/23.")
    step = artifact.get("selected_pretrain_step")
    if type(step) is not int or step < 0 or step > config.pretrain_updates:
        raise ValueError("Exact selected pretrain step is missing or incompatible.")
    if config.method in LATENT_METHODS and step == 0:
        raise ValueError("A trained forward objective requires a positive selected pretrain step.")
    return config, band, step


class NativeLatentPredictor:
    """Frozen context-only SSL inference; no forecast, targets or rollout API.

    Inputs cannot verify source-clock continuity: issuance dates/interval IDs
    remain the caller's responsibility. Device must be exactly cpu or cuda:0.
    Existing absolute provenance paths may be inaccessible after relocation.
    """

    def __init__(self, weights, device="cpu"):
        if str(device) not in ("cpu", "cuda:0"):
            raise ValueError("Device must be explicitly cpu or cuda:0.")
        self.device = torch.device(device)
        artifact = torch.load(weights, weights_only=True, map_location="cpu")
        self._config, band, self.selected_pretrain_step = _artifact(artifact, self.device)
        self._scalers = legacy._scalers(artifact.get("scalers"))
        self._bindings = legacy._bindings(artifact.get("bindings"))
        self._config_metadata = copy.deepcopy(artifact["config"])
        self._scaler_metadata = copy.deepcopy(artifact["scalers"])
        self.artifact_kind = artifact["kind"]
        self.architecture = ARCHITECTURE if band else None
        self.method = self._config.method
        self.training_kind = legacy.TRAINING_KINDS[self.method]
        self.feature_branch = (
            "selected_ema"
            if self.method == "cf_jepa"
            else ("shared_band_encoder" if band else "shared_encoder")
        )
        self.embedding_dimension = (
            self._config.cf_latent if self.method == "cf_jepa" else self._config.latent
        )
        with torch.device("meta"):
            if self.method == "cf_jepa":
                model = _LoadOnlyCF(self._config).float()
            else:
                model = (NativeBandTemporalModel if band else NativeTemporalModel)(
                    self._config.width, self._config.latent, self._config.blocks, self._config.heads
                ).float()
        state = artifact.get("model")
        _check_state(state, model.state_dict())
        for key, value in state.items():
            if (
                key.endswith(("running_var", "num_batches_tracked"))
                or key == "regularizer.global_step"
            ) and (value < 0).any():
                raise ValueError(f"Invalid nonnegative safe buffer: {key}")
        model.load_state_dict(state, strict=True, assign=True)
        self._model = model.eval().requires_grad_(False).to(self.device)

    @property
    def config_metadata(self):
        return copy.deepcopy(self._config_metadata)

    @property
    def scaler_metadata(self):
        return copy.deepcopy(self._scaler_metadata)

    @property
    def source_bindings(self):
        return copy.deepcopy(self._bindings)

    @property
    def objective_metadata(self):
        common = {
            "method": self.method,
            "training_kind": self.training_kind,
            "feature_branch": self.feature_branch,
            "architecture": self.architecture,
            "units": "latent coordinates; not acoustic dB, profiles or biological quantities",
        }
        if self.method == "cf_jepa":
            common.update(
                objective="cf_ordinal_future_zone",
                predictor_branch="online_sequence",
                target_branch="ema_teacher_sequence",
                axes=["sample", "context_token", "ordinal_zone", "latent"],
                ordinal_zones=[1, 2, 3],
                input_view="Full H96 context is outside sampled forward training crop-view support.",
                training_comparison="Normalized directions under source-defined loss; API returns raw linear predictions.",
            )
        elif self.method in LATENT_METHODS:
            common.update(
                objective="shared_future_block"
                if self.method == "shared_ssl"
                else "permuted_pairing_control",
                predictor_branch="shared_encoder_then_trained_query_head",
                target_branch="shared_encoder_not_detached",
                horizons=[1, 3, 6],
                horizon_units="native source interval offsets; not verified UTC",
                target_block_length=4,
                target_blocks_overlap=True,
                axes=["sample", "source_offset", "latent"],
            )
        else:
            common.update(objective="untrained_forward_head", latent_prediction_supported=False)
        return copy.deepcopy(common)

    def _batches(self, x, observed, metadata, query=None):
        x, observed, metadata = legacy._inputs(x, observed, metadata, self._config.history)
        if query is not None:
            query = _query(query, metadata)
        self._model.eval()
        size = min(self._config.batch_size, 64)
        for start in range(0, len(x), size):
            end = min(start + size, len(x))
            with np.errstate(over="ignore", invalid="ignore"):
                values = self._scalers.channels(x[start:end], observed[start:end])
            if not np.isfinite(values).all():
                raise ValueError("Observed normalized dB must be finite at float32 precision.")
            tensors = [
                torch.as_tensor(values, device=self.device),
                torch.as_tensor(observed[start:end].copy(order="C"), device=self.device),
                torch.as_tensor(metadata[start:end].copy(order="C"), device=self.device),
            ]
            if query is not None:
                tensors.append(
                    torch.as_tensor(query[start:end].copy(order="C"), device=self.device)
                )
            yield end - start, tensors

    def _output(self, tensor, shape):
        if (
            tensor.shape != shape
            or tensor.dtype != torch.float32
            or not torch.isfinite(tensor).all()
        ):
            raise ValueError("Latent output must have its exact finite float32 shape.")
        return tensor.cpu().numpy()

    @torch.inference_mode()
    def encode(self, x, observed, metadata):
        """Selected shared/EMA pooled embedding[N,D], with saved TRAIN scalers."""
        results = []
        for count, batch in self._batches(x, observed, metadata):
            result = self._model.encoder.encode(*batch)
            results.append(self._output(result, (count, self.embedding_dimension)))
        return np.concatenate(results)

    @torch.inference_mode()
    def predict_latents(self, x, observed, metadata, query):
        """Shared native-offset target embeddings[N,3,D]; never acoustic forecasts."""
        if self.method == "cf_jepa":
            raise ValueError(
                "CF learns ordinal future zones, not queried horizons1/3/6; use predict_cf_zones."
            )
        if self.method not in LATENT_METHODS:
            raise ValueError(f"{self.method} has an untrained forward latent head; encode only.")
        # None must not silently remove the issued query validation path.
        if query is None:
            raise ValueError("An issued native query is required for shared latent prediction.")
        results = []
        for count, batch in self._batches(x, observed, metadata, query):
            context = self._model.encoder.encode(*batch[:3])
            result = self._model.predictor(context, batch[3])
            results.append(self._output(result, (count, 3, self.embedding_dimension)))
        return np.concatenate(results)

    @torch.inference_mode()
    def predict_cf_zones(self, x, observed, metadata):
        """Raw ONLINE ordinal-zone predictions[N,96,3,D], no issued query.

        Full observed H96 is outside the randomly cropped CF training view
        distribution. Zones have no fixed1/3/6 offset or acoustic forecast claim.
        """
        if self.method != "cf_jepa":
            raise ValueError("Only CF has ordinal future-zone sequence predictors.")
        results = []
        for count, batch in self._batches(x, observed, metadata):
            sequence = self._model.online.sequence(*batch)
            result = torch.stack([p(sequence) for p in self._model.predictors], dim=2)
            results.append(self._output(result, (count, 96, 3, self.embedding_dimension)))
        return np.concatenate(results)

tools/execute_native_band_replication_jo.text:
"""Execute one exactly reviewed band job under full-owned 12/96-hour limits.

Production ROOT is this script's actual checkout, never a CLI provenance path.
Parent exceptions retain an active ledger record for root reconciliation.
No scientific fitting is authorized merely by config generation or owner budget.
"""

from __future__ import annotations

import argparse
import ast
import copy
import hashlib
import importlib.util
import inspect
import json
import math
import re
import subprocess
import time
import uuid
from dataclasses import dataclass
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ARCHITECTURE = "nonlinear_frequency_conditioned_v1"
FAMILY = "native_band_v1"
EVIDENCE = "REAL_TRAIN_DEVELOPMENT_FIT"
IMPLEMENTER = "01a0ef20-7397-7ba1-a98c-f59bc38ddcc1"
RECIPES = (
    "band_shared_ssl",
    "band_masked_ssl",
    "band_permuted_ssl",
    "band_random_frozen",
    "band_direct_end_to_end",
)
METHODS = ("shared_ssl", "masked_ssl", "permuted_ssl", "random_frozen", "direct")
ACTIVE = {"RUNNING_CUDA", "RUNNING_CPU_FIT"}
RSS_LIMIT = 22 * 2**30


def digest(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def _pairs(values):
    result = {}
    for k, v in values:
        if k in result:
            raise ValueError("Duplicate JSON identity/key.")
        result[k] = v
    return result


def read_json(path):
    def bad(value):
        raise ValueError("Nonfinite JSON policy/accounting value.")

    result = json.loads(Path(path).read_bytes(), object_pairs_hook=_pairs, parse_constant=bad)
    if not isinstance(result, dict):
        raise TypeError("Explicit JSON object required.")
    return result


def _number(value, label):
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(value)
        or value < 0
    ):
        raise ValueError(f"Invalid/nonfinite {label}.")
    return float(value)


def validate_budget(resolution):
    if (
        resolution.get("kind") != "native_band_owner_budget_resolution_v1"
        or resolution.get("status") != "ROOT_RESOLVED"
    ):
        raise ValueError("Exact owner ROOT_RESOLVED receipt required.")
    for key, value in {
        "seed7_recipe_limit_including_controls": 11,
        "revision_gpu_hours_limit_full_owned": 12,
        "aggregate_gpu_hours_limit_full_owned": 96,
    }.items():
        if type(resolution.get(key)) is not int or resolution[key] != value:
            raise ValueError("Owner budget must remain exactly11/12/96.")
    if resolution.get("single_revision_recipes") != list(RECIPES) or resolution.get(
        "original_recipes"
    ) != ["shared_ssl", "cf_jepa", "masked_ssl", "permuted_ssl", "direct", "random_frozen"]:
        raise ValueError("Owner's five band plus six original recipes differ.")
    if (
        resolution.get("prefit_source_review") != "REQUIRED_NOT_GRANTED_BY_OWNER_REPLY"
        or resolution.get("cloud_or_paid_resource_approval") is not False
        or resolution.get("whole_site_final_numeric_access") != "NOT_AUTHORIZED_BY_THIS_REPLY"
    ):
        raise ValueError("Budget reply cannot authorize source review/cloud/final access.")


def budget_totals(ledger):
    if ledger.get("gpu_limit_hours") != 96 or isinstance(ledger.get("gpu_limit_hours"), bool):
        raise ValueError("Aggregate ledger limit must equal96.")
    aggregate = _number(ledger.get("gpu_hours_spent_owned_scientific_jobs"), "aggregate hours")
    runs = ledger.get("runs")
    if not isinstance(runs, list):
        raise TypeError("Complete run ledger required.")
    if any(r.get("status") in ACTIVE for r in runs):
        raise ValueError("Another journalled scientific fit is active.")
    band_seconds = 0.0
    for record in runs:
        signature = (
            record.get("architecture") == ARCHITECTURE
            or str(record.get("method", "")).startswith("band_")
            or "native_band" in str(record.get("config", "")).lower()
            or any("native_band" in str(v) for v in record.get("command", []))
        )
        if signature and record.get("budget_family") != FAMILY:
            raise ValueError("Unaccounted historical band record; root reconciliation required.")
        if record.get("budget_family") != FAMILY:
            continue
        if record.get("status") not in {
            "COMPLETED_REAL_BAND_CUDA",
            "FAILED_REAL_BAND_CUDA_ATTEMPT",
            "COMPLETED_REAL_CUDA",
            "FAILED_REAL_CUDA_ATTEMPT",
        }:
            raise ValueError("Unknown band job status; root reconciliation required.")
        if record.get("requires_reconciliation"):
            raise ValueError("Unreconciled band attempt; no second process.")
        full = record.get("resources_full_attempt", {}).get("elapsed_full_attempt_seconds")
        seconds = record.get("elapsed_owned_seconds", full)
        seconds = _number(seconds, "full owned band attempt seconds")
        if full is not None and not math.isclose(
            seconds, _number(full, "supervised full elapsed"), abs_tol=1e-6, rel_tol=1e-9
        ):
            raise ValueError("Conflicting band attempt elapsed counters.")
        band_seconds += seconds
    if aggregate * 3600 + 1e-6 < band_seconds:
        raise ValueError("Aggregate counter undercounts band owned attempts.")
    remaining = min((96 - aggregate) * 3600, 12 * 3600 - band_seconds)
    if remaining <= 0:
        raise ValueError("Band or aggregate full-owned budget exhausted.")
    return aggregate, band_seconds / 3600, remaining


def budget_allowance(ledger):
    return budget_totals(ledger)[2]


def source_paths(root):
    """Fixed local static import closure; no review-controlled imports."""
    package = root / "src/marine_echo"
    pending = [
        root / "tools/execute_native_band_replication_job.py",
        root / "tools/prepare_native_band_replication_configs.py",
        root / "tools/native_reference_supervisor.py",
        package / "training/native_band_replication_ssl.py",
        package / "training/native_band_replication_downstream.py",
        package / "inference/native_band_replication_acoustic.py",
        package / "inference/native_band_replication_encoder.py",
        package / "inference/native_band_replication_latent.py",
    ]
    found = set()
    while pending:
        p = pending.pop().resolve()
        if p in found:
            continue
        if not p.is_file():
            raise ValueError(f"Required immutable source missing: {p}")
        found.add(p)
        for node in ast.walk(ast.parse(p.read_bytes())):
            names = []
            if isinstance(node, ast.Import):
                names = [a.name for a in node.names]
            elif isinstance(node, ast.ImportFrom):
                name = node.module or ""
                names = [name, *(name + "." + a.name for a in node.names)]
            for name in names:
                if name.startswith("marine_echo."):
                    candidate = package.joinpath(*name.split(".")[1:]).with_suffix(".py")
                    if candidate.is_file():
                        pending.append(candidate)
    for name in (
        "__init__.py",
        "models/__init__.py",
        "training/__init__.py",
        "data/__init__.py",
        "data/native_ssl_corpus.py",
        "training/aeon_corpus.py",
    ):
        p = package / name
        if not p.is_file():
            raise ValueError("Required reader/package source missing.")
        found.add(p.resolve())
    return sorted(found)


def _review_identity(review, status):
    author, coordinator, reviewer = (
        review.get(k)
        for k in ("implementer_session_id", "root_coordinator_session_id", "reviewer_session_id")
    )
    if any(
        not isinstance(v, str) or not v or v != v.strip() for v in (author, coordinator, reviewer)
    ):
        raise ValueError("Explicit author/root/reviewer session identities required.")
    if reviewer.casefold() in {IMPLEMENTER.casefold(), author.casefold(), coordinator.casefold()}:
        raise ValueError("Reviewer must be distinct from builder and root.")
    if review.get("status") != status or author != IMPLEMENTER:
        raise ValueError("Exact distinct band prefit status/implementer required.")
    if review.get("architecture") != ARCHITECTURE or review.get("evidence_kind") != EVIDENCE:
        raise ValueError("Exact real TRAIN/development band review required.")
    if sorted(review.get("allowed_roles", [])) != ["development", "train"]:
        raise ValueError("Only exact TRAIN/development roles; final test stays closed.")


def _verify_bindings(review, required, allowed_npz):
    bindings = review.get("bindings")
    if not isinstance(bindings, dict) or not bindings:
        raise ValueError("Nonempty exact bindings required.")
    verified = {}
    for value, expected in bindings.items():
        p = Path(value)
        if (
            not p.is_absolute()
            or str(p.resolve()) != value
            or not isinstance(expected, str)
            or not re.fullmatch("[0-9a-f]{64}", expected)
        ):
            raise ValueError("Canonical absolute path/SHA256 bindings required.")
        if p.suffix.lower() == ".npz" and p not in allowed_npz:
            raise ValueError("Non-TRAIN/development NPZ binding prohibited.")
        actual = digest(p)
        if actual != expected:
            raise ValueError(f"Stale binding: {p}")
        verified[value] = actual
    if any(str(p.resolve()) not in verified for p in required):
        raise ValueError(
            "Missing required wrapper/supervisor/source/runtime/config/budget binding."
        )
    return verified


@dataclass(frozen=True)
class Job:
    kind: str
    config: Path
    review: Path
    output: Path
    receipt: Path
    encoder: Path | None = None
    ancestor_review: Path | None = None
    ancestor_config: Path | None = None
    resume: Path | None = None


@dataclass
class Plan:
    job: Job
    root: Path
    config: dict
    review: dict
    ledger: dict
    command: list
    bindings: dict
    aggregate_hours: float
    band_hours: float
    deadline_seconds: float
    ledger_hash: str
    trainer_review: Path


def _fixed_inputs(root, kind):
    paths = {
        "train": root / "data/processed/native_ssl_v1/train.npz",
        "dev": root / "data/processed/native_ssl_v1/development.npz",
        "split": root / "configs/native_ssl_split_v1.json",
        "protocol": root / "docs/adr/0016-native-ssl-selection-and-source-baseline.md",
    }
    if kind == "downstream":
        paths.update(
            {
                "train-cohort": root / "data/processed/native_ssl_v1/train.json",
                "dev-cohort": root / "data/processed/native_ssl_v1/development.json",
                "adr0016": paths["protocol"],
                "protocol": root / "docs/adr/0018-native-acoustic-downstream-transfer.md",
            }
        )
    return paths


def _check_config(config, kind, root):
    # Import the fixed config generator only after every source binding verified.
    path = root / "tools/prepare_native_band_replication_configs.py"
    spec = importlib.util.spec_from_file_location("_native_band_fixed_configs", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    screens, prospective, _ = module._catalog(*module._definitions(root))
    if kind == "ssl":
        candidates = [c for c in screens.values() if "mode" not in c]
    else:
        candidates = [c for c in [*screens.values(), *prospective.values()] if "mode" in c]
    if config not in candidates:
        raise ValueError("Config differs from an executable fixed band recipe/endpoint.")


def _admit(job, root, *, config_validator=_check_config):
    root = Path(root).resolve()
    job = Job(
        **{
            k: (Path(v).resolve() if v is not None and k != "kind" else v)
            for k, v in vars(job).items()
        }
    )
    if job.kind not in ("ssl", "downstream"):
        raise ValueError("Only SSL or downstream execution.")
    if (
        not job.output.is_relative_to(root)
        or not job.receipt.is_relative_to(root)
        or job.output == job.receipt
        or job.output.is_relative_to(job.receipt)
        or job.receipt.is_relative_to(job.output)
    ):
        raise ValueError("Separate root-owned output/receipt paths required.")
    if (
        job.receipt.exists()
        or (job.output.exists() and job.resume is None)
        or (job.resume is not None and not job.output.is_dir())
    ):
        raise FileExistsError("New receipt/output required; resume explicit only.")
    if job.resume is not None and (
        not job.resume.is_file()
        or not job.resume.is_relative_to(job.output)
        or job.resume.suffix != ".pt"
    ):
        raise ValueError("Existing approved owned resume tensor path required.")
    if (job.output / "run.json").exists() or (job.output / "inference.pt").exists():
        raise FileExistsError("Completed output artifacts protected; no resume overwrite.")
    lock = root / "evidence/ssl-builder-v1/gpu-owner.lock"
    if lock.exists():
        raise ValueError("Existing GPU lock preserved; no launch.")
    config, review = read_json(job.config), read_json(job.review)
    status = "APPROVED_PREFIT" if job.kind == "ssl" else "APPROVED_DOWNSTREAM_PREFIT"
    _review_identity(review, status)
    method, mode, seed = config.get("method"), config.get("mode", "ssl_screen"), config.get("seed")
    if (
        config.get("architecture") != ARCHITECTURE
        or type(seed) is not int
        or seed not in (7, 13, 23)
        or method not in METHODS
        or config.get("history") != 96
    ):
        raise ValueError("Exact band architecture/method/seed7/13/23/H96 required.")
    if (
        method not in review.get("allowed_methods", [])
        or seed not in review.get("allowed_seeds", [])
        or (job.kind == "downstream" and mode not in review.get("allowed_modes", []))
    ):
        raise ValueError("Method/mode/seed outside exact review.")
    if job.kind == "ssl" and (
        method == "direct"
        or any(v is not None for v in (job.encoder, job.ancestor_review, job.ancestor_config))
    ):
        raise ValueError("No direct SSL screen or SSL ancestor arguments.")
    if job.kind == "downstream":
        if mode == "direct_end_to_end":
            if method != "direct" or any(
                v is not None for v in (job.encoder, job.ancestor_review, job.ancestor_config)
            ):
                raise ValueError("Direct endpoint starts random, without selected ancestor.")
        elif mode not in ("frozen_readout", "full_finetune") or any(
            v is None for v in (job.encoder, job.ancestor_review, job.ancestor_config)
        ):
            raise ValueError("Pretrained endpoints need exact encoder/ancestor review/config.")
    budget_path = root / "orchestration/native_band_budget_owner_resolution_v1.json"
    if (
        review.get("budget_resolution_path") != str(budget_path)
        or review.get("band_budget_status") != "ROOT_RESOLVED"
    ):
        raise ValueError("Explicit exact root budget-resolution path/status required.")
    inputs = _fixed_inputs(root, job.kind)
    trainer_review = job.review
    if job.resume is not None:
        value = review.get("trainer_review_path")
        if not isinstance(value, str) or not Path(value).is_absolute():
            raise ValueError("Resume approval must bind the unchanged original trainer review.")
        trainer_review = Path(value).resolve()
    elif review.get("trainer_review_path") not in (None, str(job.review)):
        raise ValueError("Fresh fitting uses this exact original trainer review.")
    required = [
        *source_paths(root),
        job.config,
        budget_path,
        root / "docs/adr/0023-owner-resolved-band-budget.md",
        root / "docs/adr/0016-native-ssl-selection-and-source-baseline.md",
        root / "docs/adr/0018-native-acoustic-downstream-transfer.md",
        root / ".venv/Scripts/python.exe",
        *inputs.values(),
    ]
    for name in ("pyproject.toml", "uv.lock"):
        required.append(root / name)
    if job.resume is not None:
        required.extend([job.resume, trainer_review])
    if job.encoder is not None:
        required += [
            job.encoder,
            job.ancestor_review,
            job.ancestor_config,
            *(job.encoder.parent / n for n in ("run.json", "inference.pt", "membership.json")),
        ]
    bindings = _verify_bindings(review, required, {inputs["train"], inputs["dev"]})
    validate_budget(read_json(budget_path))
    if review.get("approved_config") != config:
        raise ValueError("Review exact runtime config mismatch.")
    runtime = {
        **{k: str(v) for k, v in inputs.items()},
        "config": str(job.config),
        "review": str(job.review),
        "trainer-review": str(trainer_review),
        "output": str(job.output),
        "receipt": str(job.receipt),
        "device": "cuda:0",
        "kind": job.kind,
    }
    for name in ("encoder", "ancestor_review", "ancestor_config", "resume"):
        runtime[name.replace("_", "-")] = (
            str(getattr(job, name)) if getattr(job, name) is not None else None
        )
    if review.get("runtime_arguments") != runtime:
        raise ValueError("Exact approved runtime paths/arguments differ.")
    for role, key in (("train", "train_npz_sha256"), ("dev", "dev_npz_sha256")):
        if review.get(key) != bindings[str(inputs[role])]:
            raise ValueError("Review TRAIN/development identity differs.")
    if review.get("split_sha256") != bindings[str(inputs["split"])]:
        raise ValueError("Review split identity differs.")
    config_validator(config, job.kind, root)
    if job.resume is not None:
        original = read_json(trainer_review)
        _review_identity(original, status)
        _verify_bindings(
            original,
            [job.config, budget_path, *source_paths(root), *inputs.values()],
            {inputs["train"], inputs["dev"]},
        )
        if (
            original.get("band_budget_status") != "ROOT_RESOLVED"
            or original.get("budget_resolution_path") != str(budget_path)
            or original.get("approved_config") != config
            or method not in original.get("allowed_methods", [])
            or seed not in original.get("allowed_seeds", [])
            or (job.kind == "downstream" and mode not in original.get("allowed_modes", []))
        ):
            raise ValueError("Original immutable trainer prefit identity differs on resume.")
    if job.encoder is not None:
        ancestor = read_json(job.ancestor_review)
        _review_identity(ancestor, "APPROVED_PREFIT")
        # Every declared ancestor binding must remain exact; deeper ancestry/kind
        # admission stays in the unchanged downstream runner before array parsing.
        _verify_bindings(
            ancestor,
            [
                job.ancestor_config,
                budget_path,
                inputs["train"],
                inputs["dev"],
                inputs["split"],
                root / "docs/adr/0016-native-ssl-selection-and-source-baseline.md",
            ],
            {inputs["train"], inputs["dev"]},
        )
        if (
            ancestor.get("band_budget_status") != "ROOT_RESOLVED"
            or ancestor.get("budget_resolution_path") != str(budget_path)
            or ancestor["bindings"].get(str(budget_path)) != bindings[str(budget_path)]
        ):
            raise ValueError("Original independently reviewed ancestor budget missing.")
    ledger_path = root / "orchestration/native_ssl_run_ledger_v1.json"
    if ledger_path.with_suffix(".band-pending").exists():
        raise ValueError(
            "Existing unfinished band journal preserved; root reconciliation required."
        )
    ledger = read_json(ledger_path)
    aggregate, band, deadline = budget_totals(ledger)
    command = [
        str(root / ".venv/Scripts/python.exe"),
        "-u",
        "-m",
        f"marine_echo.training.native_band_replication_{job.kind}",
    ]
    for name, value in {
        **inputs,
        "config": job.config,
        "review": trainer_review,
        "output": job.output,
        "device": "cuda:0",
    }.items():
        command.extend(["--" + name, str(value)])
    for name in ("encoder", "ancestor_review", "ancestor_config", "resume"):
        value = getattr(job, name)
        if value is not None:
            command.extend(["--" + name.replace("_", "-"), str(value)])
    return Plan(
        job,
        root,
        config,
        review,
        ledger,
        command,
        bindings,
        aggregate,
        band,
        deadline,
        digest(ledger_path),
        trainer_review,
    )


def _import_supervisor(root, bindings):
    path = root / "tools/native_reference_supervisor.py"
    if digest(path) != bindings[str(path)]:
        raise ValueError("Supervisor changed after admission.")
    spec = importlib.util.spec_from_file_location("native_reference_supervisor", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if digest(path) != bindings[str(path)]:
        raise ValueError("Supervisor changed during import.")
    return module.supervise_owned


def _write_ledger(root, ledger):
    # Operational journal mutable only in root execution; historical artifacts
    # never overwritten. A denied write propagates without fallback/retry.
    target = root / "orchestration/native_ssl_run_ledger_v1.json"
    pending = target.with_suffix(".band-pending")
    with pending.open("x", encoding="utf-8") as stream:
        json.dump(ledger, stream, indent=2, allow_nan=False)
        stream.write("\n")
    pending.replace(target)


def _exclusive_json(path, value):
    with path.open("x", encoding="utf-8") as stream:
        json.dump(value, stream, indent=2, allow_nan=False)
        stream.write("\n")


def _valid_resources(resources, child):
    child_pid = child.pid
    pids = resources.get("owned_process_pids", [])
    if (
        type(child_pid) is not int
        or child_pid < 1
        or not isinstance(pids, list)
        or any(type(v) is not int or v < 1 for v in pids)
        or len(pids) != len(set(pids))
        or resources.get("owned_tree_cleanup_verified") is not True
        or type(resources.get("exit_code")) is not int
        or child_pid not in pids
        or child.poll() != resources["exit_code"]
    ):
        raise ValueError("Actual exit/owned identity/cleanup proof missing.")
    for key in (
        "elapsed_full_attempt_seconds",
        "peak_process_rss_bytes",
        "deadline_seconds",
        "rss_limit_bytes",
    ):
        _number(resources.get(key), key)


def _completion(plan):
    path = plan.job.output / "run.json"
    if not path.is_file():
        return None, "MISSING_COMPLETED_REPORT"
    report = read_json(path)
    if (
        report.get("status") != "COMPLETED"
        or report.get("architecture") != ARCHITECTURE
        or report.get("evidence_kind") != EVIDENCE
        or report.get("correctness_smoke") is not False
        or report.get("config") != plan.config
        or report.get("test_access") != "NOT_RUN"
        or report.get("review_sha256") != digest(plan.trainer_review)
    ):
        return None, "INVALID_COMPLETED_REPORT"
    if plan.job.kind == "downstream" and report.get("mode") != plan.config["mode"]:
        return None, "WRONG_COMPLETED_MODE"
    resources = report.get(
        "resources" if plan.job.kind == "ssl" else "resources_additional_downstream", {}
    )
    for key in (
        "peak_allocated_bytes",
        "peak_reserved_bytes",
        "peak_rss_bytes",
        "elapsed_gpu_seconds",
    ):
        _number(resources.get(key), key)
    if (
        max(resources["peak_allocated_bytes"], resources["peak_reserved_bytes"]) >= 10 * 2**30
        or resources["peak_rss_bytes"] >= RSS_LIMIT
    ):
        return None, "REPORT_RESOURCE_LIMIT"
    for key, file in (
        ("inference_sha256", "inference.pt"),
        ("membership_sha256", "membership.json"),
    ):
        p = plan.job.output / file
        if not p.is_file() or report.get(key) != digest(p):
            return None, "MISSING_OR_CHANGED_COMPLETION_ARTIFACT"
    return report, None


def _execute(
    plan, *, popen, supervisor, clock=time.monotonic, write_ledger=_write_ledger, started=None
):
    job, root = plan.job, plan.root
    ledger_path = root / "orchestration/native_ssl_run_ledger_v1.json"
    lock = root / "evidence/ssl-builder-v1/gpu-owner.lock"
    if lock.exists() or digest(ledger_path) != plan.ledger_hash:
        raise ValueError("GPU/ledger ownership changed after admission.")
    for path, expected in plan.bindings.items():
        if digest(path) != expected:
            raise ValueError("An admitted binding changed before launch/mutation.")
    # Fresh receipt isolates logs on retries; output belongs to the child.
    job.receipt.mkdir(parents=True, exist_ok=False)
    started = clock() if started is None else started
    record = {
        "id": job.receipt.name,
        "attempt_id": str(uuid.uuid4()),
        "status": "RUNNING_CUDA",
        "architecture": ARCHITECTURE,
        "evidence_kind": EVIDENCE,
        "budget_family": FAMILY,
        "kind": job.kind,
        "method": plan.config["method"],
        "mode": plan.config.get("mode", "ssl_screen"),
        "seed": plan.config["seed"],
        "history": plan.config["history"],
        "config": str(job.config),
        "config_sha256": digest(job.config),
        "review": str(job.review),
        "review_sha256": digest(job.review),
        "output": str(job.output),
        "receipt": str(job.receipt),
        "trainer_review": str(plan.trainer_review),
        "trainer_review_sha256": digest(plan.trainer_review),
        "budget_resolution_path": str(
            root / "orchestration/native_band_budget_owner_resolution_v1.json"
        ),
        "budget_resolution_sha256": plan.bindings[
            str(root / "orchestration/native_band_budget_owner_resolution_v1.json")
        ],
        "deadline_seconds": plan.deadline_seconds,
        "command": plan.command,
        "gpu_owner": "root",
        "resume": str(job.resume) if job.resume else None,
        "bindings": plan.bindings,
        "pid": None,
        "requires_reconciliation": True,
    }
    ledger = copy.deepcopy(plan.ledger)
    ledger["runs"].append(record)
    ledger["status"] = "REAL_BAND_SCIENTIFIC_ATTEMPT_RUNNING"
    journal_failed = False

    def journal():
        nonlocal journal_failed
        try:
            write_ledger(root, ledger)
        except BaseException:
            journal_failed = True
            raise

    journal()  # Reservation exists before spawning a child.
    try:
        with (job.receipt / "console.log").open("x", encoding="utf-8") as log:
            child = popen(plan.command, cwd=root, stdout=log, stderr=subprocess.STDOUT)
            record["pid"] = child.pid
            journal()
            resources = supervisor(
                child,
                started=started,
                deadline_seconds=plan.deadline_seconds,
                rss_limit_bytes=RSS_LIMIT,
            )
        _valid_resources(resources, child)
        elapsed = max(
            _number(resources["elapsed_full_attempt_seconds"], "full elapsed"), clock() - started
        )
        record.update(
            resources_full_attempt=resources,
            elapsed_owned_seconds=elapsed,
            exit_code=resources["exit_code"],
        )
        # The wrapper adds verification/report time; normalize both accounting
        # fields to that full owned attempt, never just child training GPU time.
        record["resources_full_attempt"]["elapsed_full_attempt_seconds"] = elapsed
        if resources.get("stopped_for") is not None and lock.exists():
            owner_raw = lock.read_bytes()
            try:
                owner = json.loads(owner_raw)
            except (ValueError, UnicodeDecodeError):
                owner = {}
            if (
                resources["owned_tree_cleanup_verified"]
                and type(owner.get("pid")) is int
                and owner.get("pid") in resources["owned_process_pids"]
                and owner.get("output") == str(job.output)
                and lock.read_bytes() == owner_raw
            ):
                lock.unlink()
                record["owned_terminated_tree_lock_cleanup"] = True
            else:
                record["unknown_lock_preserved"] = True
        stopped = (
            resources.get("stopped_for") is not None
            or elapsed >= plan.deadline_seconds
            or resources["peak_process_rss_bytes"] >= RSS_LIMIT
        )
        report, reason = (
            (None, "CHILD_EXIT_OR_SUPERVISOR_LIMIT")
            if resources["exit_code"] != 0 or stopped
            else _completion(plan)
        )
        completed = report is not None and not lock.exists()
        if lock.exists():
            reason = "GPU_LOCK_REMAINS"
        record.update(
            status="COMPLETED_REAL_BAND_CUDA" if completed else "FAILED_REAL_BAND_CUDA_ATTEMPT",
            verified_completion=completed,
            failure_reason=reason,
            owned_tree_cleanup_verified=True,
            gpu_lock_absent=not lock.exists(),
            requires_reconciliation=lock.exists(),
        )
        # Charge startup/evaluation/saves/report validation as full owned time,
        # including unsuccessful attempts and each resumed invocation.
        elapsed = max(elapsed, clock() - started)
        if elapsed >= plan.deadline_seconds and completed:
            completed = False
            record.update(
                status="FAILED_REAL_BAND_CUDA_ATTEMPT",
                verified_completion=False,
                failure_reason="FULL_OWNED_ATTEMPT_DEADLINE_AFTER_VERIFICATION",
            )
        record["elapsed_owned_seconds"] = elapsed
        record["resources_full_attempt"]["elapsed_full_attempt_seconds"] = elapsed
        ledger["gpu_hours_spent_owned_scientific_jobs"] = plan.aggregate_hours + elapsed / 3600
        ledger["native_band_gpu_hours_spent_full_owned"] = plan.band_hours + elapsed / 3600
        if completed:
            record.update(
                run_sha256=digest(job.output / "run.json"),
                resources_report=report.get(
                    "resources", report.get("resources_additional_downstream")
                ),
            )
            ledger["scientific_fits_completed"] = ledger.get("scientific_fits_completed", 0) + 1
            ledger["gpu_hours_completed_scientific_training"] = (
                ledger.get("gpu_hours_completed_scientific_training", 0)
                + record["resources_report"]["elapsed_gpu_seconds"] / 3600
            )
        ledger["status"] = (
            "REAL_BAND_ATTEMPT_COMPLETED" if completed else "REAL_BAND_ATTEMPT_FAILED"
        )
        _exclusive_json(job.receipt / "attempt.json", record)
        journal()
        return 0 if completed else (resources["exit_code"] or 1)
    except BaseException as error:
        # A supervisor/save/verification exception is NOT proof of cleanup.
        # The already journalled active record blocks every later launch.
        record.update(
            status="RUNNING_CUDA",
            requires_reconciliation=True,
            parent_exception_type=type(error).__name__,
            parent_exception=str(error),
            elapsed_owned_seconds=max(0, clock() - started),
            verified_completion=False,
        )
        record.pop("owned_tree_cleanup_verified", None)
        ledger["gpu_hours_spent_owned_scientific_jobs"] = (
            plan.aggregate_hours + record["elapsed_owned_seconds"] / 3600
        )
        ledger["native_band_gpu_hours_spent_full_owned"] = (
            plan.band_hours + record["elapsed_owned_seconds"] / 3600
        )
        ledger["status"] = "BAND_PARENT_EXCEPTION_REQUIRES_ROOT_RECONCILIATION"
        # If journalling itself failed, the prior active reservation remains.
        # No retry of that failed write through another API.
        if not journal_failed:
            journal()
        raise


def execute(job):
    started = time.monotonic()
    if not (ROOT / ".venv/Scripts/python.exe").is_file():
        raise ValueError("Execute only in the integrated scientific root checkout.")
    plan = _admit(job, ROOT)
    supervisor = _import_supervisor(ROOT, plan.bindings)
    return _execute(plan, popen=subprocess.Popen, supervisor=supervisor, started=started)


def _execute_for_test(job, root, *, popen, supervisor, config_validator, clock, writer):
    caller = inspect.stack()[1]
    if (
        Path(caller.filename).name != "test_native_band_replication_execution.py"
        or not caller.function.startswith("test_")
        or "SYNTHETIC_CORRECTNESS_ONLY" not in str(root)
    ):
        raise ValueError("Private injected root only inside synthetic test functions.")
    return _execute(
        _admit(job, root, config_validator=config_validator),
        popen=popen,
        supervisor=supervisor,
        clock=clock,
        write_ledger=writer,
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--kind", required=True, choices=("ssl", "downstream"))
    for flag in ("config", "review", "output", "receipt"):
        parser.add_argument("--" + flag, required=True, type=Path)
    for flag in ("encoder", "ancestor-review", "ancestor-config", "resume"):
        parser.add_argument("--" + flag, type=Path)
    args = parser.parse_args()
    raise SystemExit(execute(Job(**vars(args))))


if __name__ == "__main__":
    main()
